<?php
require '../config.php';header('Content-Type: application/json; charset=utf-8');
try{$type=$_GET['type']??'';$id=(int)($_GET['id']??0);$data=[];if($type==='districts'){$s=$pdo->prepare('SELECT id,name FROM districts WHERE region_id=? ORDER BY name');$s->execute([$id]);$data=$s->fetchAll();}elseif($type==='wards'){$s=$pdo->prepare('SELECT id,name FROM wards WHERE district_id=? ORDER BY name');$s->execute([$id]);$data=$s->fetchAll();}elseif($type==='villages'){$s=$pdo->prepare('SELECT id,name FROM villages WHERE ward_id=? ORDER BY name');$s->execute([$id]);$data=$s->fetchAll();}else{http_response_code(400);echo json_encode(['success'=>false,'error'=>'Invalid location type']);exit;}echo json_encode(['success'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'error'=>$e->getMessage()]);}
